Looking at the implementation and ticket requirements, I need to write comprehensive tests that cover:

1. **Normal formatting** with different exponents (JPY=0, USD=2, KWD=3, CLF=4)
2. **Rounding behavior** with HALF_EVEN (the critical halfway cases from the ticket)
3. **Negative zero handling** (key edge case mentioned explicitly)
4. **Amount parsing** edge cases (scientific notation, whitespace, padding)
5. **Error handling** (invalid amounts, non-finite values, unknown currency, and order of validation)

Let me verify my understanding of the expected behavior with a few key examples from the ticket:
- `"2.675"` USD → `"2.68"` (round up, 8 is even)
- `"2.665"` USD → `"2.66"` (round down, 6 is even)
- `"-0.004"` USD → `"0.00"` (negative zero handling)
- `"1234.5"` JPY → `"1234"` (no decimal point when exponent=0)
- Currency lookup must happen before amount validation (so unknown currency + invalid amount → KeyError, not ValueError)

```json
{"code": "import pytest
import impl


class TestFormatAmount:
    def setup_method(self):
        self.exponents = {
            'USD': 2,
            'JPY': 0,
            'KWD': 3,
            'CLF': 4,
        }

    # Normal path - different exponents
    def test_usd_two_decimals(self):
        assert impl.format_amount("2.50", "USD", self.exponents) == "2.50"

    def test_jpy_zero_decimals(self):
        assert impl.format_amount("1234.5", "JPY", self.exponents) == "1234"

    def test_kwd_three_decimals(self):
        assert impl.format_amount("1.2345", "KWD", self.exponents) == "1.234"

    def test_clf_four_decimals(self):
        assert impl.format_amount("1.23456", "CLF", self.exponents) == "1.2346"

    # Rounding with HALF_EVEN
    def test_round_half_even_up(self):
        # 2.675 -> 2.68 (8 is even)
        assert impl.format_amount("2.675", "USD", self.exponents) == "2.68"

    def test_round_half_even_down(self):
        # 2.665 -> 2.66 (6 is even)
        assert impl.format_amount("2.665", "USD", self.exponents) == "2.66"

    def test_negative_rounding(self):
        assert impl.format_amount("-2.675", "USD", self.exponents) == "-2.68"

    # Negative zero handling
    def test_negative_zero_usd(self):
        # -0.004 rounds to -0.00 which becomes "0.00"
        assert impl.format_amount("-0.004", "USD", self.exponents) == "0.00"

    def test_negative_zero_jpy(self):
        # -0.4 rounds to -0 which becomes "0"
        assert impl.format_amount("-0.4", "JPY", self.exponents) == "0"

    # Amount parsing edge cases
    def test_scientific_notation(self):
        assert impl.format_amount("1E+2", "USD", self.exponents) == "100.00"

    def test_whitespace(self):
        assert impl.format_amount("  1.50  ", "USD", self.exponents) == "1.50"

    def test_fewer_decimals_zero_padded(self):
        assert impl.format_amount("1.2", "USD", self.exponents) == "1.20"

    def test_more_decimals_truncated(self):
        assert impl.format_amount("1.2345", "USD", self.exponents) == "1.23"

    # Error cases - invalid amount format
    def test_empty_string_raises_value_error(self):
        with pytest.raises(ValueError):
            impl.format_amount("", "USD", self.exponents)

    def test_invalid_text_raises_value_error(self):
        with pytest.raises(ValueError):
            impl.format_amount("abc", "USD", self.exponents)

    def test_multiple_decimals_raises_value_error(self):
        with pytest.raises(ValueError):
            impl.format_amount("1.2.3", "USD", self.exponents)

    def test_infinity_raises_value_error(self):
        with pytest.raises(ValueError):
            impl.format_amount("Infinity", "USD", self.exponents)

    def test_nan_raises_value_error(self):
        with pytest.raises(ValueError):
            impl.format_amount("NaN", "USD", self.exponents)

    # Error cases - currency lookup
    def test_unknown_currency_raises_key_error(self):
        with pytest.raises(KeyError):
            impl.format_amount("1.50", "XXX", self.exponents)

    def test_currency_lookup_before_amount_validation(self):
        # Unknown currency caught before invalid amount validation
        with pytest.raises(KeyError):
            impl.format_amount("abc", "XXX", self.exponents)
"}
